256			t.Fatalf("want ErrLogRead wrapping the cause, got %v", err)
257		}
258		if failures != 0 {
259			t.Fatalf("an unread stream has no failed logs, got %d", failures)
260		}
261		if out.Len() != 0 {
262			t.Fatalf("no complete line means no output, got %q", out.String())
263		}
264	}
