// Read as EOF, still produces its event: clean EOF must not drop it.
func TestNormalizeFinalizeUnterminatedTailArrivesWithEOF(t *testing.T) {
	tail := `{"timestamp":"2026-01-02T00:00:09Z","action":"tail"}` // no "\n"
