			failures, err := NormalizeReader(src, &out)
			if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
				t.Fatalf("want ErrLogRead wrapping the cause, got %v", err)
			}
			if failures != 0 {
