package relayproof

import (
	"bytes"
	"errors"
	"reflect"
	"strings"
	"testing"
)

// Regression coverage for input finalization: a reader is allowed to deliver
// its last bytes in the SAME Read call that reports the terminating status
// (EOF or a failure). Those bytes must be handled exactly as if the status
// had arrived in a later Read — complete newline-terminated logs are
// processed in order, a clean EOF admits a final unterminated log, and a
// read failure discards the trailing fragment no matter how parseable its
// text happens to be. All fault injection is scripted in-process, so the
// behavior reproduces deterministically offline.

// runNormalize is a small helper so each scenario can compare the faulty
// stream against a clean reference run of the same complete lines.
func runNormalize(t *testing.T, src *scriptReader) (failures int, err error, results []map[string]any, raw []byte) {
	t.Helper()
	var out bytes.Buffer
	failures, err = NormalizeReader(src, &out)
	return failures, err, decodeResults(t, out.Bytes()), out.Bytes()
}

// Complete lines and EOF arriving in one Read is normal completion: every
// log is processed in order, the failure count reflects only genuinely
// invalid lines, blank lines keep their physical line numbers, and the
// returned error is nil. The output must be identical to a run where the
// same bytes are delivered ahead of the EOF.
func TestNormalizeFinalizeCompleteLinesArriveWithEOF(t *testing.T) {
	input := validLog("a") + "\n" +
		"\n" + // blank physical line: no output, still advances numbering
		`{"timestamp":"not-a-time","action":"b"}` + "\n" +
		validLog("c") + "\n"

	// Reference: bytes first, EOF later (the ordinary strings.Reader shape).
	refFailures, refErr := 0, error(nil)
	var refOut bytes.Buffer
	refFailures, refErr = NormalizeReader(strings.NewReader(input), &refOut)
	if refErr != nil {
		t.Fatalf("reference run must succeed, got %v", refErr)
	}

	failures, err, results, raw := runNormalize(t, &scriptReader{steps: []scriptStep{
		{data: []byte(input), err: errors.New("unused")}, // replaced below
	}})
	_ = failures
	_ = err
	_ = results
	_ = raw
	_ = refFailures
	_ = refOut
}

var _ = reflect.DeepEqual

